#!/bin/sh
# Generates BuildInfo.swift with the current git commit and date.
# Run before `swift build` to embed version info, and always before tagging a release.
#
# BuildInfo.swift is a tracked file, not a build product: SwiftPM prebuild plugins run
# sandboxed and cannot shell out to git, so there is no way to stamp this automatically.
# That means the committed stamp is whatever was last generated by hand, and `--version`
# can name a commit the binary was not built from.
#
# That matters more than a cosmetic version string. `Examples/XcodeAuditProject` prints
# `--version` alongside its results specifically so a reader can tell whether an audit ran
# on a current binary — one project vendored a months-old build for weeks, and an audit
# against it would have mis-measured several rules, one of which reported 133 findings
# where the current version reports 1. A stamp that silently lies defeats the check it
# exists to support.
#
# So the stamp now reports what it actually knows:
#   - a clean tree at a known commit  -> "2192779"
#   - a tree with uncommitted changes -> "2192779-dirty"
#   - no git at all                   -> "dev"
#   - never generated                 -> "unreleased" (the committed placeholder)
#
# A `-dirty` suffix is the common case for a locally built binary and is not a problem in
# itself; it just stops that build from claiming to be the commit it was derived from.
#
# The committed file holds "unreleased" rather than a commit hash on purpose. A hash cannot
# be truthful before the commit containing it exists, so stamping one by hand always names
# the *previous* commit — which is the small silent lie this script is meant to remove. The
# Homebrew formula runs this script in its install block, so a release build carries a real
# hash; a source build that skips it says "unreleased", which is accurate.
COMMIT=$(git rev-parse --short HEAD 2>/dev/null || echo "dev")
if [ "$COMMIT" != "dev" ] && ! git diff-index --quiet HEAD -- 2>/dev/null; then
    COMMIT="$COMMIT-dirty"
fi
DATE=$(date +%Y-%m-%d)
YEAR=$(date +%Y)
cat > Sources/A11yCheckCLI/BuildInfo.swift <<EOF
/*
   Copyright $YEAR CVS Health and/or one of its affiliates

   Licensed under the Apache License, Version 2.0 (the "License");
   you may not use this file except in compliance with the License.
   You may obtain a copy of the License at

       http://www.apache.org/licenses/LICENSE-2.0

   Unless required by applicable law or agreed to in writing, software
   distributed under the License is distributed on an "AS IS" BASIS,
   WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.
   See the License for the specific language governing permissions and
   limitations under the License.
 */

// Generated by generate-build-info.sh — do not edit by hand.
let buildCommit = "$COMMIT"
let buildDate = "$DATE"
EOF
